import requests, time
from concurrent.futures import ThreadPoolExecutor
BASE="http://10.0.179.146:7860"
def post(d):
    t=time.time()
    try:
        r=requests.post(BASE+"/api/Flag", json={"data":d}, timeout=25)
        return (round(time.time()-t,2), r.status_code, r.text[:80])
    except Exception as e:
        return (-1, "EXC", str(e)[:50])

vals = {
 "str":"abc", "int":1, "float":1.5, "bool":True, "None":None,
 "list":["x"], "tuple":("x",), "dict":{"k":"v"}, "set":{1},
 "bytes":b"abc", "empty_str":"", "zero":0,
}
# test each value as name with fixed str greeting, and as greeting with fixed str name
tests=[]
for k,v in vals.items():
    tests.append((f"name={k}/greet=str", [v, "abc"]))
    tests.append((f"name=str/greet={k}", ["abc", v]))

with ThreadPoolExecutor(max_workers=12) as ex:
    for label,d in tests:
        f=ex.submit(post,d)
        print(f"{label:28s} -> {f.result()}")
EOF
python3 matrix.py
